import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import api from '../../services/api';
export default {
  name: 'AdminStores',
  data() {
    return {
      stores: [],
      q: '',
      posUsersCountByStore: {}
    };
  },
  computed: {
    filteredStores() {
      const q = String(this.q || '').toLowerCase().trim();
      if (!q) return this.stores;
      return this.stores.filter(s => String(s.store_name || '').toLowerCase().includes(q) || String(s.full_name || '').toLowerCase().includes(q) || String(s.email || '').toLowerCase().includes(q));
    }
  },
  async created() {
    const {
      data
    } = await api.get('/admin/stores');
    this.stores = data;
    await this.refreshPosUserCounts();
  },
  methods: {
    async refreshPosUserCounts() {
      const map = {};
      for (const s of this.stores) {
        try {
          const {
            data
          } = await api.get(`/admin/stores/${s.id}/pos-users`);
          map[s.id] = Array.isArray(data) ? data.length : 0;
        } catch (_) {
          map[s.id] = 0;
        }
      }
      this.posUsersCountByStore = map;
    }
  }
};
